import{_ as e,o as r,c as d,a0 as o}from"./chunks/framework.jwovEGr5.js";const p=JSON.parse('{"title":"sharecli serve — draft SLOs","description":"","frontmatter":{},"headers":[],"relativePath":"ops/SLO.md","filePath":"ops/SLO.md"}'),s={name:"ops/SLO.md"};function a(n,t,i,c,l,h){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="sharecli-serve-—-draft-slos" tabindex="-1">sharecli serve — draft SLOs <a class="header-anchor" href="#sharecli-serve-—-draft-slos" aria-label="Permalink to &quot;sharecli serve — draft SLOs&quot;">​</a></h1><p>Draft service-level objectives for the <code>sharecli serve</code> HTTP surface. Numbers are starting targets for local/daemon ops; tighten once scrape history exists.</p><h2 id="slo-1-—-liveness-availability" tabindex="-1">SLO-1 — Liveness availability <a class="header-anchor" href="#slo-1-—-liveness-availability" aria-label="Permalink to &quot;SLO-1 — Liveness availability&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Objective</strong></td><td><code>GET /healthz</code> returns HTTP 200 with <code>{&quot;status&quot;:&quot;ok&quot;}</code></td></tr><tr><td><strong>Target</strong></td><td>≥ 99.5% successful probes over a rolling 30-day window</td></tr><tr><td><strong>Probe</strong></td><td>External or sidecar HTTP GET every 15–30s</td></tr><tr><td><strong>Error budget</strong></td><td>~3.6 hours downtime / 30 days</td></tr><tr><td><strong>Notes</strong></td><td>Liveness only — process is up. Does not imply readiness for traffic.</td></tr></tbody></table><h2 id="slo-2-—-controlled-restart-readiness-drain" tabindex="-1">SLO-2 — Controlled restart / readiness drain <a class="header-anchor" href="#slo-2-—-controlled-restart-readiness-drain" aria-label="Permalink to &quot;SLO-2 — Controlled restart / readiness drain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Objective</strong></td><td>During intentional shutdown (Ctrl-C or thermal critical), <code>GET /readyz</code> flips to HTTP 503 before the listener exits</td></tr><tr><td><strong>Target</strong></td><td>≤ 2 unplanned serve restarts per process per 24h (thermal-critical and crash-driven)</td></tr><tr><td><strong>Probe</strong></td><td>Compare <code>/readyz</code> vs <code>/healthz</code> during drain; alert on restart storms via notifier webhooks</td></tr><tr><td><strong>Error budget</strong></td><td>2 restarts / day; burn rate &gt; 1 restart / hour warrants investigation</td></tr><tr><td><strong>Notes</strong></td><td>Readiness is distinct from liveness (<code>/readyz</code> vs <code>/healthz</code> in <code>src/commands/serve.rs</code>).</td></tr></tbody></table><h2 id="slo-3-—-metrics-scrape-freshness" tabindex="-1">SLO-3 — Metrics scrape freshness <a class="header-anchor" href="#slo-3-—-metrics-scrape-freshness" aria-label="Permalink to &quot;SLO-3 — Metrics scrape freshness&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Objective</strong></td><td><code>GET /metrics/prometheus</code> returns Prometheus text exposition (content-type <code>text/plain; version=0.0.4</code>) including <code>sharecli_process_*</code> / <code>sharecli_health_check_*</code> series when processes are tracked</td></tr><tr><td><strong>Target</strong></td><td>≥ 99% successful scrapes at ≤ 60s scrape interval</td></tr><tr><td><strong>Probe</strong></td><td>Prometheus (or equivalent) scrape job against <code>/metrics/prometheus</code></td></tr><tr><td><strong>Error budget</strong></td><td>~7 failed scrapes / day at 1/min cadence</td></tr><tr><td><strong>Notes</strong></td><td>Includes process/health gauges and HTTP RED series (<code>sharecli_http_requests_total</code>, <code>sharecli_http_errors_total</code>, <code>sharecli_http_request_duration_ms_*</code>). See <code>docs/ops/otel.md</code> and Grafana <code>docs/ops/grafana/sharecli-serve.json</code>.</td></tr></tbody></table><h2 id="slo-4-—-authn-failure-burn" tabindex="-1">SLO-4 — AuthN failure burn <a class="header-anchor" href="#slo-4-—-authn-failure-burn" aria-label="Permalink to &quot;SLO-4 — AuthN failure burn&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Objective</strong></td><td>Protected routes reject bad credentials without flooding (401 rate bounded)</td></tr><tr><td><strong>Target</strong></td><td><code>rate(sharecli_http_unauthorized_total) / rate(sharecli_http_requests_total)</code> ≤ 10% over 5m, sustained &lt;10m</td></tr><tr><td><strong>Probe</strong></td><td>Prometheus series from <code>/metrics/prometheus</code> + JSONL <code>auth_fail</code> in audit log</td></tr><tr><td><strong>Error budget</strong></td><td>Short bursts OK (misconfigured clients); 10m sustained burn → investigate IdP/JWKS/token</td></tr><tr><td><strong>Alert</strong></td><td><code>SharecliAuthFailBurn</code> in <code>docs/ops/alertmanager/sharecli.yml</code></td></tr></tbody></table><h2 id="mapping-to-probes" tabindex="-1">Mapping to probes <a class="header-anchor" href="#mapping-to-probes" aria-label="Permalink to &quot;Mapping to probes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Role</th><th>Success</th></tr></thead><tbody><tr><td><code>/healthz</code></td><td>Liveness</td><td>200 + <code>status=ok</code></td></tr><tr><td><code>/readyz</code></td><td>Readiness</td><td>200 while serving; 503 once shutdown requested</td></tr><tr><td><code>/metrics/prometheus</code></td><td>Scrape</td><td>200 + required metric name prefixes</td></tr></tbody></table><h2 id="out-of-scope-for-now" tabindex="-1">Out of scope (for now) <a class="header-anchor" href="#out-of-scope-for-now" aria-label="Permalink to &quot;Out of scope (for now)&quot;">​</a></h2><ul><li>Continuous profiling push agent (Pyroscope); opt-in pprof HTTP is in <code>docs/ops/profiling.md</code></li><li>Live PagerDuty routing keys committed to git (use env / secret store)</li><li>Formal signed on-call roster</li></ul><p>Alert <strong>rule pack + severity routing + runbooks</strong> ship in <code>docs/ops/alertmanager/sharecli.yml</code> and <code>docs/ops/alerting.md</code>.</p><h2 id="bench-linked-targets-c08" tabindex="-1">Bench-linked targets (C08) <a class="header-anchor" href="#bench-linked-targets-c08" aria-label="Permalink to &quot;Bench-linked targets (C08)&quot;">​</a></h2><p>Draft performance budgets tied to Criterion benches and load scripts. Reproduce via <a href="./../eval/REPRO.html"><code>docs/eval/REPRO.md</code></a>. Harbor/SWE-bench remain out of scope per <a href="./../adr/0002-eval-surface-out-of-scope.html"><code>docs/adr/0002-eval-surface-out-of-scope.md</code></a>.</p><table tabindex="0"><thead><tr><th>ID</th><th>Surface</th><th>Budget</th><th>Harness</th></tr></thead><tbody><tr><td>BENCH-1</td><td><code>config_toml_from_str</code></td><td>p95 &lt; 1 ms</td><td><code>benches/config_parse.rs</code></td></tr><tr><td>BENCH-2</td><td><code>pool_new_and_list_empty</code></td><td>p95 &lt; 100 ms</td><td><code>benches/pool_list.rs</code></td></tr><tr><td>BENCH-3</td><td><code>prometheus_render_32</code></td><td>p95 &lt; 500 µs</td><td><code>benches/prometheus_render.rs</code></td></tr><tr><td>LOAD-1</td><td><code>GET /healthz</code> burst</td><td>≥ 99% success over N=200</td><td><code>scripts/load/healthz_burst.sh</code></td></tr><tr><td>LOAD-2</td><td><code>GET /healthz</code> latency</td><td>hyperfine p50 trend</td><td><code>scripts/bench/hyperfine-healthz.sh</code></td></tr></tbody></table><h3 id="measurement-log-append-only" tabindex="-1">Measurement log (append-only) <a class="header-anchor" href="#measurement-log-append-only" aria-label="Permalink to &quot;Measurement log (append-only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>SHA</th><th>Surface</th><th>Observed</th><th>Host</th></tr></thead><tbody><tr><td>2026-07-10</td><td><em>(pending first soft bench.yml run)</em></td><td>BENCH-1..3 + LOAD-1</td><td>budgets declared; no baseline yet</td><td>ubuntu-latest (CI)</td></tr><tr><td>2026-07-10</td><td><em>(feat/sharecli-w2-perf-gate)</em></td><td>BENCH-1..3 gate</td><td>seeded baseline JSON = SLO p95 budgets; <code>bench-gate</code> fails if mean &gt; 1.5× baseline (50% regression); soft <code>criterion</code> job retained</td><td>ubuntu-latest (CI)</td></tr></tbody></table><h3 id="baseline-gate-notes-append-only" tabindex="-1">Baseline gate notes (append-only) <a class="header-anchor" href="#baseline-gate-notes-append-only" aria-label="Permalink to &quot;Baseline gate notes (append-only)&quot;">​</a></h3><ul><li><strong>2026-07-10:</strong> Hard-ish per-PR gate added as job <code>bench-gate</code> in <code>.github/workflows/bench.yml</code>. Compares Criterion <code>target/criterion/&lt;bench&gt;/new/estimates.json</code> means to <code>docs/eval/baselines/criterion-baseline.json</code> via <code>scripts/check-bench-baseline.py</code>. Default max regression <strong>50%</strong>. Seeded means equal draft SLO p95 budgets (BENCH-1..3) so the gate is non-flaky until real CI means are re-seeded with <code>scripts/seed-bench-baseline.py</code>. Criterion <code>--save-baseline ci-gate</code> is used in CI for local HTML compare artifacts; exit status comes from the Python checker, not Criterion itself.</li></ul>',22)])])}const b=e(s,[["render",a]]);export{p as __pageData,b as default};
